/** 추후 OpenAI로 교체할 수 있는 MVP 문단 생성 서비스입니다. */
package com.dandimate.durooduroo.ai.service;
import com.dandimate.durooduroo.common.auth.MemberTokenResolver; import com.dandimate.durooduroo.common.exception.BusinessException; import com.dandimate.durooduroo.member.domain.MemberRole; import com.dandimate.durooduroo.member.repository.MemberRepository; import com.dandimate.durooduroo.memory.repository.MemoryEntryRepository; import com.dandimate.durooduroo.scroll.domain.*; import com.dandimate.durooduroo.scroll.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AiParagraphService { private final MemoryEntryRepository entries; private final ScrollRepository scrolls; private final ParagraphRepository paragraphs; private final MemberRepository members; public AiParagraphService(MemoryEntryRepository e,ScrollRepository s,ParagraphRepository p,MemberRepository m){entries=e;scrolls=s;paragraphs=p;members=m;} public void requireHost(String roomId,String authorization){String token=MemberTokenResolver.resolve(authorization);var me=members.findByRoomIdAndMemberToken(roomId,token).orElseThrow(()->new BusinessException("MEMBER_FORBIDDEN","방 참여자만 실행할 수 있습니다."));if(me.getRole()!=MemberRole.HOST)throw new BusinessException("HOST_ONLY","방장만 실행할 수 있습니다.");} @Transactional public Scroll generate(String roomId){String body=entries.findAllByRoomId(roomId).stream().filter(e->e.getContent()!=null&&!e.getContent().isBlank()).map(e->e.getContent()).reduce((a,b)->a+" "+b).orElse("아직 기록된 기억이 없습니다."); Scroll scroll=scrolls.save(Scroll.create(roomId,body)); paragraphs.save(Paragraph.create(roomId,scroll.getId(),body)); return scroll;} }
